// processador-com-di.mjs — recebe as dependências PRONTAS de quem chama.
export function criarProcessadorDePagamento(dependencias) {
  if (typeof dependencias?.calcularTaxa !== 'function') {
    throw new Error('dependência calcularTaxa precisa ser uma função');
  }
  if (typeof dependencias?.notificar !== 'function') {
    throw new Error('dependência notificar precisa ser uma função');
  }

  return {
    processar(pedido) {
      if (typeof pedido?.total !== 'number' || pedido.total < 0) {
        throw new Error('pedido precisa ter total numérico maior ou igual a 0');
      }
      const taxa = dependencias.calcularTaxa(pedido.total); // COMO? ela decide
      const valorFinal = pedido.total + taxa;
      dependencias.notificar(`Pagamento de R$ ${valorFinal.toFixed(2)} aprovado`); // COMO? ela decide
      return { total: pedido.total, taxa, valorFinal, status: 'aprovado' };
    },
  };
}

// app.mjs — produção injeta as dependências de verdade.
const processador = criarProcessadorDePagamento({
  calcularTaxa: (total) => total * 0.1, // taxa de 10%
  notificar: (mensagem) => enviarEmailReal(mensagem),
});

// teste.mjs — o teste injeta fakes: rápido, sem e-mail, sem surpresa.
const notificacoes = [];
const processadorDeTeste = criarProcessadorDePagamento({
  calcularTaxa: () => 5, // taxa fixa: previsível
  notificar: (mensagem) => notificacoes.push(mensagem), // grava em vez de enviar
});

// Passo 1: o processador — as dependências chegam prontas, de fora.
export function criarProcessadorDePagamento(dependencias) {
  return {
    processar(pedido) {
      const taxa = dependencias.calcularTaxa(pedido.total);   // COMO? ela decide
      const valorFinal = pedido.total + taxa;
      dependencias.notificar(`Pagamento de R$ ${valorFinal.toFixed(2)} aprovado`);
      return { total: pedido.total, taxa, valorFinal, status: 'aprovado' };
    },
  };
}

// Passo 2: produção — a factory injeta as versões reais.
function criarAppDePagamento() {
  return criarProcessadorDePagamento({
    calcularTaxa: (total) => total * 0.1, // 10% de taxa
    notificar: (mensagem) => enviarEmailReal(mensagem), // e-mail de verdade
  });
}

// Passo 3: teste — a MESMA factory de teste injeta fakes.
function criarAppDePagamentoDeTeste() {
  const notificacoes = [];
  const processador = criarProcessadorDePagamento({
    calcularTaxa: () => 5, // taxa fixa, previsível
    notificar: (mensagem) => notificacoes.push(mensagem), // grava, não envia
  });
  return { processador, notificacoes };
}

// Passo 4: os dois mundos, o mesmo processar.
const producao = criarAppDePagamento();
console.log(producao.processar({ total: 100 }).valorFinal); // imprime: 110

const teste = criarAppDePagamentoDeTeste();
console.log(teste.processar({ total: 100 }).valorFinal); // imprime: 105

// Passo 5: a prova — o fake gravou o que o processador mandou.
console.log(teste.notificacoes); // imprime: ['Pagamento de R$ 105.00 aprovado']
